def unseal(token: str, seal_key: str, aad: str = "") -> str | None:
    if not token:
        return None
    try:
        raw = base64.b64decode(token)
        ad = aad.encode() if aad else None
        return AESGCM(_key(seal_key)).decrypt(raw[:12], raw[12:], ad).decode()
    except Exception:
        return None

@property
    def seal_key(self) -> str:
        """Fall back to the internal token so a dev boot never stores creds in the clear."""
        return self.CREDENTIAL_SEAL_KEY or self.INTERNAL_SERVICE_TOKEN

